<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useLearning} from '@/store.js';
import {insightsApi} from '@/services/insights.js';
import {teachingApi} from '@/services/teaching.js';
import {memoryApi} from '@/services/memory.js';
import InterventionComposer from './InterventionComposer.vue';
import {RefreshCw,ArrowUpRight,Plus} from '@/components/app/icons.js';
const route=useRoute(),router=useRouter(),store=useLearning();
const rooms=ref([]),classId=ref(String(route.query.class||store.currentClassId||store.task?.classId||'')),taskId=ref(String(route.query.scopeTask||route.query.task||'')),start=ref(String(route.query.start||'')),end=ref(String(route.query.end||'')),data=ref(null),error=ref(''),loading=ref(false),tab=ref('knowledge'),selected=ref(null),student=ref(null),compose=ref(false),point=ref(null),review=ref(null),note=ref(''),decision=ref('confirmed'),busy=ref(false),reviewKey=ref('');let generation=0;
const tabs=[{value:'knowledge',label:'知识点'},{value:'questions',label:'题目分析'},{value:'students',label:'学生'},{value:'review',label:'待核对'},{value:'interventions',label:'教学安排'}];
async function load(){const g=++generation;loading.value=true;error.value='';data.value=null;selected.value=null;student.value=null;try{if(!rooms.value.length)rooms.value=await teachingApi.classes();if(!classId.value)classId.value=rooms.value[0]?.id||'';if(!classId.value)return;const value=await insightsApi.get({classId:classId.value,taskId:taskId.value,start:start.value,end:end.value});if(g!==generation)return;data.value=value;store.currentClassId=classId.value;await router.replace({query:{...route.query,class:classId.value,scopeTask:taskId.value||undefined,start:start.value||undefined,end:end.value||undefined}});}catch(e){if(g===generation)error.value=e.message}finally{if(g===generation)loading.value=false}}
watch(()=>route.query.class,id=>{if(id&&String(id)!==classId.value)classId.value=String(id)});watch(()=>route.query.task,id=>{if(id&&String(id)!==taskId.value)taskId.value=String(id)});
watch(classId,()=>{taskId.value='';load()});watch([taskId,start,end],load);load();onBeforeUnmount(()=>generation++);
function source(e){store.selectTask(e.taskId);store.selectStudent(e.studentId);router.push({name:'insights',query:{task:e.taskId,class:classId.value}});}
function arrange(kp){point.value=kp;compose.value=true}
function cases(kp){router.push({name:'cases',query:{knowledge:kp.id,q:kp.name+' 独立作答错误',grade:data.value.class.grade,subject:data.value.class.subject,scenario:'other',interventionClass:classId.value,interventionTask:taskId.value||data.value.tasks[0]?.id}})}
async function openReview(e){note.value='';review.value=e;reviewKey.value=crypto.randomUUID();}
async function saveReview(){if(busy.value)return;busy.value=true;try{const m=await memoryApi.overview({studentId:review.value.studentId,classId:classId.value});const ev=[...m.items.flatMap(i=>i.evidence),...m.unlinkedEvidence].find(e=>e.eventId===review.value.eventId);await insightsApi.review({studentId:review.value.studentId,classId:classId.value,knowledgeId:ev?.knowledgeId,evidenceId:ev?.evidenceId,reason:note.value,decision:decision.value,requestKey:reviewKey.value,expectedRevision:m.revision});review.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
const labels={members:'当前成员',tasks:'任务',startedStudents:'已开始学生',submittedStudents:'已提交学生',unsubmittedStudents:'仍有未提交',overdueStudents:'有逾期学生',attempts:'作答尝试',answeredQuestions:'已答题目',independentCorrectQuestions:'独立正确题目',independentCorrectStudents:'独立正确学生'};
</script>
<template>
<section class="analytics-workspace">
<div class="ops-analytics-heading"><h2>班级概览</h2><AppButton :disabled="!data?.tasks.length" @click="arrange(null)"><Plus :size="16"/>安排补充教学</AppButton></div>
<div class="analytics-toolbar"><AppSelect v-model="classId" label="学情班级" :options="rooms.map(c=>({value:c.id,label:c.name}))"/><AppSelect :model-value="taskId||'all'" @update:model-value="taskId=$event==='all'?'':$event" label="任务范围" :options="[{value:'all',label:'全部任务'},...(data?.tasks||[]).map(t=>({value:t.id,label:t.title}))]"/><AppDisclosure class="ops-filter-dates"><template #title>日期范围</template><div><label>开始日期<Input type="date" v-model="start" aria-label="开始日期"/></label><label>结束日期<Input type="date" v-model="end" aria-label="结束日期"/></label></div></AppDisclosure><AppButton variant="ghost" aria-label="刷新学情" @click="load"><RefreshCw :size="17"/></AppButton><InfoTip label="统计口径">参与人数为当前成员的当前任务状态。作答证据按所选时间过滤，同一学生、任务、发布题目只计一道，最近一次作答决定当前结果；尝试次数另列。独立正确仅计已程序核验的检查题。</InfoTip></div>
<ElSkeleton v-if="loading" animated :rows="3" aria-label="读取班级记录…"/><AppAlert type="error" v-if="error" class="form-error" role="alert">{{error}} <AppButton variant="outline" @click="load">重试</AppButton></AppAlert>
<template v-if="data">
<div class="analytics-metrics"><div v-for="(label,key) in {members:'班级学生',submittedStudents:'已提交',unsubmittedStudents:'待提交',independentCorrectQuestions:'独立正确题目'}" :key="key"><span>{{label}}</span><strong>{{data.stats[key]}}</strong></div></div><AppDisclosure class="ops-disclosure ops-metric-details"><template #title>全部统计</template><dl><div v-for="(label,key) in labels" :key="key"><dt>{{label}}</dt><dd>{{data.stats[key]}}</dd></div></dl></AppDisclosure>
<p v-if="data.range.unknownTimeExcluded" class="muted">{{data.range.unknownTimeExcluded}} 条时间待核对的记录未纳入当前区间。</p><AppTabs v-model="tab" :items="tabs"/>
<Surface class="analytics-content">
<div v-if="tab==='knowledge'" class="table-container"><AppTable><thead><tr><th>知识点</th><th>作答 / 全班</th><th>独立正确</th><th>需要关注</th><th>详情</th><th>操作</th></tr></thead><tbody><tr v-for="k in data.knowledge" :key="k.id"><td><button class="analytics-text-button" @click="selected=k">{{k.name}}</button></td><td>{{k.counts.answeredStudents}} / {{k.counts.classStudents}}</td><td>{{k.counts.independentCorrectStudents}}</td><td>{{k.counts.strengthenStudents}}</td><td><AppDisclosure class="ops-table-details"><template #title>统计明细</template><dl><div><dt>程序核验学生</dt><dd>{{k.counts.verifiedStudents}}</dd></div><div><dt>有独立错误证据</dt><dd>{{k.counts.independentErrorStudents}}</dd></div><div><dt>证据不足</dt><dd>{{k.counts.insufficientStudents}}</dd></div><div><dt>待复测 / 已复测</dt><dd>{{k.counts.pendingRetestStudents}} / {{k.counts.retestedStudents}}</dd></div></dl></AppDisclosure></td><td><AppButton variant="ghost" @click="arrange(k)">安排教学</AppButton><AppButton variant="ghost" @click="cases(k)">教学案例</AppButton></td></tr></tbody></AppTable><AppEmpty v-if="!data.knowledge.length" class="empty-state">尚无已发布知识点</AppEmpty></div>
<div v-if="tab==='questions'" class="analytics-question-grid"><article v-for="q in data.questions" :key="q.id"><small>{{q.taskTitle}}</small><InfoTip label="题目版本">{{q.versionId||'历史版本'}}</InfoTip><h3>{{q.equation||q.prompt}}</h3><dl class="focus-question-stats"><div v-for="(label,key) in {students:'作答人数',correctStudents:'正确',incorrectStudents:'有误',unverifiedStudents:'待核对',helpedStudents:'有帮助'}" :key="key"><dt>{{label}}</dt><dd>{{q[key]}}</dd></div></dl><AppButton variant="outline" @click="selected={name:q.equation||q.prompt,evidence:q.evidence}">查看 {{q.attempts}} 次原始作答</AppButton></article></div>
<div v-if="tab==='students'" class="table-container"><AppTable><thead><tr><th>学生</th><th>提交 / 分配任务</th><th>未提交</th><th>逾期</th><th>尝试次数</th><th>独立正确题目</th><th>操作</th></tr></thead><tbody><tr v-for="s in data.students" :key="s.id"><td>{{s.name}}</td><td>{{s.submitted}} / {{s.assigned}}</td><td>{{s.unsubmitted}}</td><td>{{s.overdue}}</td><td>{{s.metrics.attempts}}</td><td>{{s.metrics.independentCorrectQuestions}}</td><td><AppButton variant="outline" @click="student=s">学习过程</AppButton></td></tr></tbody></AppTable></div>
<div v-if="tab==='review'" class="analytics-queue"><article v-for="e in data.reviewQueue" :key="e.eventId+e.reviewKind"><div><Status>{{e.manualReviews?.length?(e.manualReviews.at(-1).note?.startsWith('人工确认')?'已核对':'待补充'):e.reviewKind}}</Status><strong>{{e.studentName}}</strong><p v-if="e.equation" class="exam-math">{{e.equation}}</p><p v-if="e.answer">原答：{{e.answer}}</p><p>{{e.reason}}</p><p v-for="r in e.manualReviews||[]" :key="r.id">{{r.note}}</p></div><AppButton variant="outline" @click="openReview(e)">人工核对</AppButton><RouteButton :route="'memory?studentId='+e.studentId+'&classId='+classId" secondary>关联修订</RouteButton></article><AppEmpty v-if="!data.reviewQueue.length" class="empty-state">暂无待核对内容</AppEmpty></div>
<div v-if="tab==='interventions'" class="analytics-queue"><article v-for="i in data.interventions" :key="i.id"><div><h3>{{i.content}}</h3><p v-for="r in i.recipients" :key="r.studentId">{{r.studentName}} 　 {{r.status}} 　 {{r.outcome?.label||'历史说明'}}<span v-if="r.outcome?.needsHelp"> 　 仍有帮助或待核对记录</span></p></div><RouteButton :route="'insights?task='+i.taskId" secondary>查看与反馈</RouteButton></article><AppEmpty v-if="!data.interventions.length" class="empty-state">暂无补充教学安排</AppEmpty></div>
</Surface>
<AppDisclosure class="ops-disclosure" v-if="tab==='knowledge'&&data.knowledge.some(k=>k.counts.independentErrorStudents>0)"><template #title>需要关注的知识点</template><div class="analytics-difficulties"><article v-for="k in data.knowledge.filter(k=>k.counts.independentErrorStudents>0)" :key="k.id"><h3>{{k.name}}</h3><p>{{k.counts.independentErrorStudents}} 名学生有独立错误证据，{{k.counts.pendingRetestStudents}} 名仍待错题独立复测。</p><AppButton variant="outline" @click="selected=k">查看原始依据</AppButton></article></div></AppDisclosure>
<p v-if="data.stats.inactiveRecords" class="muted">{{data.stats.inactiveRecords}} 条移出成员的历史分配未计入当前班级人数。</p>
</template>
<AppDialog :open="!!selected" @update:open="!$event&&(selected=null)" :title="selected?.name||'原始依据'" content-class="student-detail-dialog"><div class="analytics-evidence"><article v-for="e in selected?.evidence||[]" :key="e.evidenceId||e.eventId"><small>{{data.students.find(s=>s.id===e.studentId)?.name||'学生记录'}} 　 {{e.timeReliable?new Date(e.occurredAt).toLocaleString('zh-CN'):'时间待核对'}}</small><InfoTip label="记录版本">{{e.lessonVersionId||'原任务'}}</InfoTip><h3>{{e.equation||e.prompt||e.label}}</h3><p v-if="e.answer">原答：{{e.answer}}</p><p>{{e.reason}}</p><Status>{{e.label||e.verification}}</Status><AppButton v-if="e.taskId" variant="ghost" @click="source(e)">原任务<ArrowUpRight :size="14"/></AppButton></article></div></AppDialog>
<AppDialog :open="!!student" @update:open="!$event&&(student=null)" :title="student?.name+'的学习记录'" content-class="student-detail-dialog"><template v-if="student"><RouteButton :route="'memory?studentId='+student.id+'&classId='+classId" secondary>学习记忆与补救依据</RouteButton><div class="analytics-evidence"><article v-for="r in student.records" :key="r.taskId"><h3>{{data.tasks.find(t=>t.id===r.taskId)?.title}}</h3><p>{{r.observation||'尚未提交解释'}}</p><p v-if="r.feedback">教师反馈：{{r.feedback}}</p><AppButton variant="outline" @click="source({studentId:student.id,taskId:r.taskId})">原始学习过程</AppButton></article></div></template></AppDialog>
<AppDialog :open="!!review" @update:open="!$event&&(review=null)" title="人工核对"><p>{{review?.equation}} → {{review?.answer}}</p><p>{{review?.reason}}</p><label class="field-label">处理结论<AppSelect v-model="decision" label="核对结论" :options="[{value:'confirmed',label:'确认并记录意见'},{value:'returned',label:'退回补充'}]"/></label><label class="field-label">核对意见<Textarea v-model="note"/></label><AppAlert type="error" v-if="error" class="form-error">{{error}}</AppAlert><AppButton :disabled="busy||!note.trim()" @click="saveReview">保存核对</AppButton></AppDialog>
<InterventionComposer v-if="data" v-model:open="compose" :report="data" :knowledge="point" @saved="load"/>
</section>
</template>
